import React from 'react';

interface FormFieldProps {
  label: string;
  type?: string;
  error?: string;
}

export function FormField({ label, type = 'text', error }: FormFieldProps) {
  return (
    <label style={{ display: 'flex', flexDirection: 'column', gap: '6px', fontSize: '{{token:typography.scale.sm}}' }}>
      <span style={{ color: '{{token:colors.text.secondary}}' }}>{label}</span>
      <input
        type={type}
        style={{
          border: `1px solid ${error ? '{{token:colors.accent.danger}}' : '{{token:colors.base.border}}'}`,
          borderRadius: '{{token:spacing.card.borderRadius}}',
          padding: '{{token:spacing.sidebar.padding}}',
          color: '{{token:colors.text.primary}}',
          background: '{{token:colors.base.surface}}',
        }}
      />
      {error ? <span style={{ color: '{{token:colors.accent.danger}}', fontSize: '{{token:typography.scale.xs}}' }}>{error}</span> : null}
    </label>
  );
}
